package com.huy.enterprise.inventory; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import com.huy.enterprise.product.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*; @Service @RequiredArgsConstructor class WarehouseService {private final WarehouseRepository repo; Warehouse entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Warehouse not found: "+id));}List<WarehouseResponse> all(){return repo.findAll().stream().map(WarehouseResponse::from).toList();}WarehouseResponse get(UUID id){return WarehouseResponse.from(entity(id));}@Transactional WarehouseResponse save(UUID id,WarehouseRequest r){if(id==null&&repo.existsByWarehouseCode(r.warehouseCode()))throw new ConflictException("Warehouse code already exists");var w=id==null?new Warehouse():entity(id);w.setWarehouseCode(r.warehouseCode());w.setName(r.name());w.setAddress(r.address());w.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());return WarehouseResponse.from(repo.save(w));}} @Service @RequiredArgsConstructor class InventoryService {private final InventoryItemRepository repo;private final WarehouseRepository warehouses;private final ProductRepository products; InventoryItem entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Inventory item not found: "+id));}List<InventoryResponse> all(){return repo.findAll().stream().map(InventoryResponse::from).toList();}List<InventoryResponse> low(){return repo.findLowStockItems().stream().map(InventoryResponse::from).toList();}InventoryResponse get(UUID id){return InventoryResponse.from(entity(id));}@Transactional InventoryResponse save(UUID id,InventoryRequest r){var w=warehouses.findById(r.warehouseId()).orElseThrow(()->new ResourceNotFoundException("Warehouse not found: "+r.warehouseId()));var p=products.findById(r.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found: "+r.productId()));if(id==null&&repo.existsByWarehouseAndProduct(w,p))throw new ConflictException("Inventory item already exists for warehouse and product");var i=id==null?new InventoryItem():entity(id);i.setWarehouse(w);i.setProduct(p);i.setQuantity(r.quantity());i.setLowStockThreshold(r.lowStockThreshold());i.setLastUpdatedAt(OffsetDateTime.now());return InventoryResponse.from(repo.save(i));}}
